// The PNGs the map symbols are drawn from, as data URIs: a canvas read from a file:// image is tainted, a data URI is not.
// Source PNGs are in assets/ (IPA names in ../README.md). Regenerate: base64 each PNG.
globalThis.ModoAssets = {
  pin: 'data:image/png;base64,',
  pinSelected: 'data:image/png;base64,',
  pinBusy: 'data:image/png;base64,',
  cluster: 'data:image/png;base64,',
};
